-- Venue Live Guest "Hari Sumpah Pemuda". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara sumpahpemuda), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'sumpahpemuda', 'Hari Sumpah Pemuda (28 Oktober)', 'sumpahpemuda', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 117, 'center 38%',
  $t${"name":"Sumpah Pemuda","orn":"diamond","ui":{"ivory":"#FFF8EE","white":"#FFFFFF","soft":"#F6E3D3","soft2":"#E3B9A0","accent":"#A61E22","deep":"#5A1517","ink":"#2B1210","mute":"#8A6A5E","line":"#EBD3C4","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFFBF4","ink":"#2B1210","accent":"#A61E22","gold":"#C9A227","leaf":"#F6E3D3","hbg":"rgba(255,248,238,.94)","hline":"#E3B9A0","motif":"diamond"},"hud":{"bg":"rgba(90,21,23,.86)","acc":"#F2D98A","on":"#2B1210"},"scr":{"wine":"#5A1517","veil":"255,248,238"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'sumpahpemuda');
